__load_custom_0() {
#!/usr/bin/env bash

_login_zsh_find() {
    local path

    path=$(command -v zsh) || return 1
    printf '%s' "$path"
}

_login_zsh_current() {
    local account
    local output
    local user

    user=$(id -un) || return 1
    output=$(getent passwd "$user") || return 1
    account=${output##*:}
    [ -n "$account" ] || return 1
    printf '%s' "$account"
}

_login_zsh_allowed() {
    local allowed
    local equivalent=''
    local shell_path=$1

    [ -r /etc/shells ] || return 1
    while IFS= read -r allowed; do
        case "$allowed" in
            ''|'#'*) continue ;;
        esac
        if [ "$allowed" = "$shell_path" ]; then
            printf '%s' "$allowed"
            return 0
        fi
        if [ -z "$equivalent" ] &&
            [ -e "$allowed" ] && [ -e "$shell_path" ] && [ "$allowed" -ef "$shell_path" ]; then
            equivalent=$allowed
        fi
    done < /etc/shells
    if [ -n "$equivalent" ]; then
        printf '%s' "$equivalent"
        return 0
    fi
    return 1
}

login-zsh_is_installed() {
    local current
    local shell_path

    shell_path=$(_login_zsh_find) || return 1
    current=$(_login_zsh_current) || return 1
    [ "$current" = "$shell_path" ] ||
        { [ -e "$current" ] && [ -e "$shell_path" ] && [ "$current" -ef "$shell_path" ]; }
}

login-zsh_install() {
    local allowed_shell
    local shell_path
    local status
    local user

    shell_path=$(_login_zsh_find)
    status=$?
    [ "$status" -eq 0 ] || fatal "$status"
    allowed_shell=$(_login_zsh_allowed "$shell_path")
    status=$?
    [ "$status" -eq 0 ] || fatal "$status"
    user=$(id -un)
    status=$?
    [ "$status" -eq 0 ] || fatal "$status"
    run_as_root chsh -s "$allowed_shell" "$user"
    printf '\n\033[1;31mACTION REQUIRED:\033[0m\n'
    printf 'Sign out and sign in again to use the new login shell.\n'
    printf '\n'
}
}

__load_custom_1() {
#!/usr/bin/env bash

ZIMFW_MODULE_UPDATE_NEEDED=0
ZIMFW_UPGRADE_NEEDED=0

_zimfw_run_action() {
    local action=$1
    local zim_home=${ZIM_HOME:-$HOME/.zim}
    local zimrc=${ZIM_CONFIG_FILE:-$HOME/.zimrc}

    run_checked env ZIM_HOME="$zim_home" ZIM_CONFIG_FILE="$zimrc" \
        zsh -c 'source "$1" "$2" -q' -- "$zim_home/zimfw.zsh" "$action"
}

zimfw_is_installed() {
    local zim_home=${ZIM_HOME:-$HOME/.zim}
    local zimrc=${ZIM_CONFIG_FILE:-$HOME/.zimrc}

    [ -f "$zim_home/zimfw.zsh" ] &&
        [ -f "$zim_home/init.zsh" ] &&
        [ -f "$zimrc" ]
}

_zimfw_check_updates() {
    local module_output
    local status
    local version_output
    local zim_home=${ZIM_HOME:-$HOME/.zim}
    local zimrc=${ZIM_CONFIG_FILE:-$HOME/.zimrc}

    ZIMFW_MODULE_UPDATE_NEEDED=0
    ZIMFW_UPGRADE_NEEDED=0
    version_output=$(env ZIM_HOME="$zim_home" ZIM_CONFIG_FILE="$zimrc" \
        zsh -c 'source "$1" "$2" -v' \
        -- "$zim_home/zimfw.zsh" check-version 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$version_output" >&2; fatal "$status"; }
    case "$version_output" in
        *'Latest zimfw version is '*) ZIMFW_UPGRADE_NEEDED=1 ;;
    esac

    module_output=$(env ZIM_HOME="$zim_home" ZIM_CONFIG_FILE="$zimrc" \
        zsh -c 'source "$1" "$2" -v' \
        -- "$zim_home/zimfw.zsh" check 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$module_output" >&2; fatal "$status"; }
    case "$module_output" in
        *': Update available'*) ZIMFW_MODULE_UPDATE_NEEDED=1 ;;
    esac

    [ "$ZIMFW_UPGRADE_NEEDED" -eq 1 ] || [ "$ZIMFW_MODULE_UPDATE_NEEDED" -eq 1 ]
}

zimfw_install() {
    local installer
    local status
    local temp_dir
    local zim_home=${ZIM_HOME:-$HOME/.zim}
    local zimrc=${ZIM_CONFIG_FILE:-$HOME/.zimrc}
    local zsh_bin

    if [ -f "$zim_home/zimfw.zsh" ] && [ -f "$zimrc" ]; then
        if [ ! "$zim_home/init.zsh" -nt "$zimrc" ]; then
            _zimfw_run_action init
        fi
        return 0
    fi
    if [ -e "$zim_home" ]; then
        printf '%s exists but is not a complete Zimfw installation\n' "$zim_home" >&2
        fatal 1
    fi

    temp_dir=$(mktemp -d "${TMPDIR:-/tmp}/hostinit-zimfw.XXXXXX")
    status=$?
    [ "$status" -eq 0 ] || fatal "$status"
    installer=$temp_dir/install.zsh
    curl --fail --show-error --silent --location \
        --connect-timeout 10 --retry 3 --proto '=https' --tlsv1.2 \
        'https://raw.githubusercontent.com/zimfw/install/master/install.zsh' \
        -o "$installer"
    status=$?
    [ "$status" -eq 0 ] || { rm -rf "$temp_dir"; fatal "$status"; }
    zsh_bin=$(command -v zsh)
    status=$?
    [ "$status" -eq 0 ] || { rm -rf "$temp_dir"; fatal "$status"; }
    env SHELL="$zsh_bin" ZIM_HOME="$zim_home" ZIM_CONFIG_FILE="$zimrc" \
        zsh "$installer"
    status=$?
    rm -rf "$temp_dir"
    [ "$status" -eq 0 ] || fatal "$status"
}

zimfw_update() {
    local changed=0
    local zim_home=${ZIM_HOME:-$HOME/.zim}
    local zimrc=${ZIM_CONFIG_FILE:-$HOME/.zimrc}

    _zimfw_check_updates || return 1
    if [ "$ZIMFW_UPGRADE_NEEDED" -eq 1 ]; then
        _zimfw_run_action upgrade
        changed=1
    fi
    if [ ! "$zim_home/init.zsh" -nt "$zimrc" ]; then
        _zimfw_run_action init
    fi
    if [ "$ZIMFW_MODULE_UPDATE_NEEDED" -eq 1 ]; then
        _zimfw_run_action update
        changed=1
    fi
    [ "$changed" -eq 1 ] || return 1
    return 0
}
}

