    [ "$status" -eq 0 ] || { rm -rf "$temp_dir"; fatal "$status"; }
    env NONINTERACTIVE=1 /bin/bash "$installer"
    status=$?
    rm -rf "$temp_dir"
    [ "$status" -eq 0 ] || fatal "$status"

