}

_docker_codename() {
    _os_release_value VERSION_CODENAME || fatal $?
}

_docker_configure_service() {
    local user
    local user_groups

    run_as_root systemctl enable docker
    run_as_root systemctl start docker
    user=$(id -un)
    [ "$user" = root ] && return 0
    user_groups=$(id -nG "$user")
    case " $user_groups " in
        *' docker '*) ;;
        *)
            run_as_root usermod -aG docker "$user"
