TUI_ACTIVE=0
STTY_STATE=''
ACTION=''
MODE='install'
APT_METADATA_REFRESHED=0
APT_INSTALLED_CACHE_READY=0
APT_INSTALLED_PACKAGES=''
BREW_METADATA_REFRESHED=0
BREW_INSTALLED_CACHE_READY=0
BREW_INSTALLED_FORMULAE=''
BREW_INSTALLED_CASKS=''

fatal() {
    local status=${1:-1}

    case "$status" in
        ''|*[!0-9]*|0)
            status=1
            ;;
    esac
    exit "$status"
}

run_checked() {
    local status

    "$@"
    status=$?
    [ "$status" -eq 0 ] || fatal "$status"
}

run_as_root() {
    if [ "$EUID" -eq 0 ]; then
        run_checked "$@"
    else
        run_checked sudo "$@"
    fi
}

_print_status() {
    local color=$1
    local item
    local message=$2

    shift 2
    printf '\n\033[%sm==> %s' "$color" "$message"
    for item in "$@"; do
        printf ' %s' "$item"
    done
    printf '\033[0m\n'
}

print_step() {
    _print_status '1;36' "$@"
}

print_success() {
    _print_status '1;32' "$@"
}

print_skip() {
    _print_status '1;33' "$@"
}

_os_release_value() {
    local requested_key=$1
    local key
    local value

    [ -r /etc/os-release ] || return 1
    while IFS='=' read -r key value; do
        [ "$key" = "$requested_key" ] || continue
        value=${value#\"}
        value=${value%\"}
        [ -n "$value" ] || return 1
        printf '%s' "$value"
        return 0
    done < /etc/os-release
    return 1
}

restore_terminal() {
    local status=$?

    if [ "$TUI_ACTIVE" -eq 1 ]; then
        stty "$STTY_STATE"
        TUI_ACTIVE=0
        printf '\033[?25h\033[?1049l'
    fi
    return "$status"
}

trap restore_terminal EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 129' HUP

detect_platform() {
    local system_name
    local os_id

    system_name=$(uname -s) || return $?
    case "$system_name" in
        Darwin)
            PLATFORM='macos'
            return 0
            ;;
        Linux)
            os_id=$(_os_release_value ID) || return $?
            case "$os_id" in
                debian|ubuntu)
                    PLATFORM=$os_id
                    return 0
                    ;;
            esac
            ;;
    esac
    return 1
}

activate_terminal() {
    stty -echo -icanon min 1 time 0 || return $?
    TUI_ACTIVE=1
    printf '\033[?1049h\033[?25l\033[2J\033[H'
}

node_is_descendant() {
    local ancestor=$2
    local candidate=$1

    while [ "$candidate" -ge 0 ]; do
        [ "$candidate" -eq "$ancestor" ] && return 0
        candidate=${NODE_PARENTS[$candidate]}
    done
    return 1
}

visit_node_and_ancestors() {
    local node_index=$1
    local visitor=$2

    shift 2
    while [ "$node_index" -ge 0 ]; do
        "$visitor" "$node_index" "$@"
        node_index=${NODE_PARENTS[$node_index]}
    done
}

include_tool_in_node_counts() {
    local installed=$2
    local node_index=$1

    NODE_ENABLED[$node_index]=1
    NODE_TOTAL_TOOLS[$node_index]=$((${NODE_TOTAL_TOOLS[$node_index]} + 1))
    if [ "$installed" -eq 1 ]; then
        NODE_INSTALLED_TOOLS[$node_index]=$((${NODE_INSTALLED_TOOLS[$node_index]} + 1))
    fi
}

increment_node_selected_tools() {
    local node_index=$1

    NODE_SELECTED_TOOLS[$node_index]=$((${NODE_SELECTED_TOOLS[$node_index]} + 1))
}

increment_node_selectable_tools() {
    local node_index=$1

    NODE_SELECTABLE_TOOLS[$node_index]=$((${NODE_SELECTABLE_TOOLS[$node_index]} + 1))
}

rebuild_visible_nodes() {
    local node_index
    local parent
    local visible

    VISIBLE_NODES=()
    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        if [ "${NODE_ENABLED[$node_index]}" -ne 1 ]; then
            continue
        fi

        visible=1
        parent=${NODE_PARENTS[$node_index]}
        while [ "$parent" -ge 0 ]; do
            if [ "${EXPANDED_NODES[$parent]}" -ne 1 ]; then
                visible=0
                break
            fi
            parent=${NODE_PARENTS[$parent]}
        done
        if [ "$visible" -eq 1 ]; then
            VISIBLE_NODES[${#VISIBLE_NODES[@]}]=$node_index
        fi
    done
}

check_installed_tools() {
    local status
    local tool_index

    TOOL_INSTALLED=()
    for ((tool_index = 0; tool_index < TOOL_COUNT; tool_index++)); do
        TOOL_INSTALLED[$tool_index]=0
        if [ "${TOOL_ENABLED[$tool_index]}" -eq 1 ]; then
            tool_is_installed "$tool_index"
            status=$?
            case "$status" in
                0) TOOL_INSTALLED[$tool_index]=1 ;;
                1) ;;
                *) return "$status" ;;
            esac
        fi
    done
}

tool_is_selectable() {
    local tool_index=$1

    [ "${TOOL_ENABLED[$tool_index]}" -eq 1 ] || return 1
    tool_supports_action "$tool_index" "$MODE" || return 1
    if [ "$MODE" = install ]; then
        [ "${TOOL_INSTALLED[$tool_index]}" -eq 0 ]
    else
        [ "${TOOL_INSTALLED[$tool_index]}" -eq 1 ]
    fi
}

refresh_selectable_counts() {
    local node_index
    local tool_index

    # Count supported actions using the installation status cached by the TUI.
    NODE_SELECTABLE_TOOLS=()
    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        NODE_SELECTABLE_TOOLS[$node_index]=0
    done
    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        tool_index=${NODE_TOOL_INDEXES[$node_index]}
        if [ "$tool_index" -ge 0 ] && tool_is_selectable "$tool_index"; then
            visit_node_and_ancestors "$node_index" increment_node_selectable_tools
        fi
    done
}

clear_selection() {
    local tool_index

    for ((tool_index = 0; tool_index < TOOL_COUNT; tool_index++)); do
        SELECTED_TOOLS[$tool_index]=0
    done
    refresh_selectable_counts
    refresh_selection_counts
}

initialize_tui() {
    local node_index
    local tool_index

    check_installed_tools || return $?

    SELECTED_TOOLS=()
    EXPANDED_NODES=()
    NODE_ENABLED=()
    NODE_INSTALLED_TOOLS=()
    NODE_SELECTED_TOOLS=()
    NODE_TOTAL_TOOLS=()
    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        EXPANDED_NODES[$node_index]=0
        NODE_ENABLED[$node_index]=0
        NODE_INSTALLED_TOOLS[$node_index]=0
        NODE_TOTAL_TOOLS[$node_index]=0
        tool_index=${NODE_TOOL_INDEXES[$node_index]}
        if [ "$tool_index" -ge 0 ] && [ "${TOOL_ENABLED[$tool_index]}" -eq 1 ]; then
            visit_node_and_ancestors "$node_index" include_tool_in_node_counts \
                "${TOOL_INSTALLED[$tool_index]}"
        fi
    done

    CURRENT_POSITION=0
    VIEWPORT_START=0
    TUI_MESSAGE=''
    clear_selection
    rebuild_visible_nodes
}

refresh_selection_counts() {
    local node_index
    local tool_index

    SELECTED_TOOL_COUNT=0
    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        NODE_SELECTED_TOOLS[$node_index]=0
    done

    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        tool_index=${NODE_TOOL_INDEXES[$node_index]}
        if [ "${NODE_ENABLED[$node_index]}" -eq 1 ] &&
            [ "$tool_index" -ge 0 ] &&
            [ "${SELECTED_TOOLS[$tool_index]}" -eq 1 ]; then
            SELECTED_TOOL_COUNT=$((SELECTED_TOOL_COUNT + 1))
            visit_node_and_ancestors "$node_index" increment_node_selected_tools
        fi
    done
}

node_selection_state() {
    local node_index=$1
    local selected=${NODE_SELECTED_TOOLS[$node_index]}
    local total=${NODE_SELECTABLE_TOOLS[$node_index]}

    if [ "$selected" -eq 0 ]; then
        NODE_SELECTION_STATE='none'
    elif [ "$selected" -eq "$total" ]; then
        NODE_SELECTION_STATE='all'
    else
        NODE_SELECTION_STATE='partial'
    fi
}

node_is_selectable() {
    [ "${NODE_SELECTABLE_TOOLS[$1]}" -gt 0 ]
}

read_terminal_size() {
    local columns
    local rows
    local size

    size=$(stty size 2>/dev/null) || size=''
    rows=${size%% *}
    columns=${size#* }
    case "$rows" in
        ''|*[!0-9]*|0) rows=${LINES:-24} ;;
    esac
    case "$columns" in
        ''|*[!0-9]*|0) columns=${COLUMNS:-80} ;;
    esac
    case "$rows" in
        ''|*[!0-9]*|0) rows=24 ;;
    esac
    case "$columns" in
        ''|*[!0-9]*|0) columns=80 ;;
    esac
    [ "$rows" -ge 3 ] || rows=3
    [ "$columns" -ge 1 ] || columns=1

    TERMINAL_ROWS=$rows
    TERMINAL_COLUMNS=$columns
    if [ "$TERMINAL_ROWS" -ge 5 ]; then
        TUI_VERTICAL_PADDING=1
        TUI_NODE_CAPACITY=$((TERMINAL_ROWS - 4))
    else
        TUI_VERTICAL_PADDING=0
        TUI_NODE_CAPACITY=$((TERMINAL_ROWS - 2))
    fi
}

update_viewport() {
    local count=${#VISIBLE_NODES[@]}
    local maximum_start

    read_terminal_size
    if [ "$count" -eq 0 ]; then
        VIEWPORT_START=0
        return 0
    fi
    if [ "$CURRENT_POSITION" -lt "$VIEWPORT_START" ]; then
        VIEWPORT_START=$CURRENT_POSITION
    elif [ "$CURRENT_POSITION" -ge $((VIEWPORT_START + TUI_NODE_CAPACITY)) ]; then
        VIEWPORT_START=$((CURRENT_POSITION - TUI_NODE_CAPACITY + 1))
    fi

    maximum_start=$((count - TUI_NODE_CAPACITY))
    [ "$maximum_start" -ge 0 ] || maximum_start=0
    [ "$VIEWPORT_START" -le "$maximum_start" ] || VIEWPORT_START=$maximum_start
    [ "$VIEWPORT_START" -ge 0 ] || VIEWPORT_START=0
}

print_tui_line() {
    local line=$1
    local style=${2:-}

    printf '%s%.*s\033[0m\033[K' "$style" "$TERMINAL_COLUMNS" "$line"
}

build_footer() {
    local available_columns
    local position_prefix=''

    if [ "${#VISIBLE_NODES[@]}" -gt "$TUI_NODE_CAPACITY" ]; then
        position_prefix="$((CURRENT_POSITION + 1))/${#VISIBLE_NODES[@]} | "
    fi
    available_columns=$((TERMINAL_COLUMNS - ${#position_prefix}))

    if [ "$available_columns" -ge 96 ]; then
        TUI_FOOTER='Space select | a all | Tab mode | h/l fold | j/k move | Ctrl+u/d page | Enter review | q quit'
    elif [ "$available_columns" -ge 71 ]; then
        TUI_FOOTER='Space select | a all | Tab mode | h/l fold | j/k move | Enter review | q quit'
    elif [ "$available_columns" -ge 48 ]; then
        TUI_FOOTER='Space select | Tab mode | Enter review | q quit'
    elif [ "$available_columns" -ge 30 ]; then
        TUI_FOOTER='Space | Tab mode | Enter | q quit'
    else
        TUI_FOOTER='Enter | q'
    fi
    TUI_FOOTER="${position_prefix}${TUI_FOOTER}"
}

render_tui() {
    local cursor
    local indent
    local indicator
    local line
    local marker
    local mode_label='Install'
    local node_index
    local position
    local position_end
    local state
    local style
    local tool_index
    local visible_count=${#VISIBLE_NODES[@]}

    [ "$MODE" = 'update' ] && mode_label='Update'
    update_viewport
    position_end=$((VIEWPORT_START + TUI_NODE_CAPACITY))
    [ "$position_end" -le "$visible_count" ] || position_end=$visible_count

    printf '\033[H'
    print_tui_line "hostinit - ${PLATFORM} - ${mode_label} | Selected: ${SELECTED_TOOL_COUNT}"
    printf '\n'
    [ "$TUI_VERTICAL_PADDING" -eq 0 ] || printf '\033[K\n'
    for ((position = VIEWPORT_START; position < position_end; position++)); do
        node_index=${VISIBLE_NODES[$position]}
        tool_index=${NODE_TOOL_INDEXES[$node_index]}
        printf -v indent '%*s' "$((${NODE_DEPTHS[$node_index]} * 2))" ''

        cursor=' '
        [ "$position" -eq "$CURRENT_POSITION" ] && cursor='>'
        style=''
        if ! node_is_selectable "$node_index"; then
            style=$'\033[90m'
        fi
        if [ "$position" -eq "$CURRENT_POSITION" ]; then
            if [ -n "$style" ]; then
                style=$'\033[1;90m'
            else
                style=$'\033[1m'
            fi
        fi
        node_selection_state "$node_index"
        state=$NODE_SELECTION_STATE
        case "$state" in
            all) marker='x' ;;
            partial) marker='-' ;;
            *) marker=' ' ;;
        esac
        indicator=''
        if [ "$tool_index" -lt 0 ]; then
            if [ "${EXPANDED_NODES[$node_index]}" -eq 1 ]; then
                indicator='v'
            else
                indicator='>'
            fi
        fi
        line="$cursor $indent[$marker] ${NODE_LABELS[$node_index]}"
        [ -z "$indicator" ] || line="$line $indicator"
        if [ "$tool_index" -lt 0 ]; then
            if [ "$MODE" = update ]; then
                line="$line (${NODE_SELECTED_TOOLS[$node_index]}/${NODE_SELECTABLE_TOOLS[$node_index]})"
            else
                line="$line (${NODE_INSTALLED_TOOLS[$node_index]}/${NODE_TOTAL_TOOLS[$node_index]})"
            fi
        fi
        print_tui_line "$line" "$style"
        printf '\n'
    done
    [ "$TUI_VERTICAL_PADDING" -eq 0 ] || printf '\033[K\n'
    if [ -n "$TUI_MESSAGE" ]; then
        print_tui_line "$TUI_MESSAGE" $'\033[1;33m'
    else
        build_footer
        print_tui_line "$TUI_FOOTER" $'\033[2m'
    fi
    printf '\033[J'
}

toggle_current_node() {
    local candidate
    local node_index
    local target=1
    local tool_index

    [ "${#VISIBLE_NODES[@]}" -gt 0 ] || return 0
    node_index=${VISIBLE_NODES[$CURRENT_POSITION]}
    node_is_selectable "$node_index" || return 0

    node_selection_state "$node_index"
    [ "$NODE_SELECTION_STATE" = all ] && target=0
    for ((candidate = 0; candidate < NODE_COUNT; candidate++)); do
        tool_index=${NODE_TOOL_INDEXES[$candidate]}
        if [ "${NODE_ENABLED[$candidate]}" -eq 1 ] &&
            [ "$tool_index" -ge 0 ] &&
            tool_is_selectable "$tool_index" &&
            node_is_descendant "$candidate" "$node_index"; then
            SELECTED_TOOLS[$tool_index]=$target
        fi
    done
    refresh_selection_counts
}

toggle_all_tools() {
    local target=0
    local tool_index

    for ((tool_index = 0; tool_index < TOOL_COUNT; tool_index++)); do
        if tool_is_selectable "$tool_index" &&
            [ "${SELECTED_TOOLS[$tool_index]}" -eq 0 ]; then
            target=1
            break
        fi
    done

    for ((tool_index = 0; tool_index < TOOL_COUNT; tool_index++)); do
        if tool_is_selectable "$tool_index"; then
            SELECTED_TOOLS[$tool_index]=$target
        fi
    done
    refresh_selection_counts
}

move_down() {
    local count=${#VISIBLE_NODES[@]}

    [ "$count" -gt 0 ] || return 0
    CURRENT_POSITION=$(((CURRENT_POSITION + 1) % count))
}

move_up() {
    local count=${#VISIBLE_NODES[@]}

    [ "$count" -gt 0 ] || return 0
    CURRENT_POSITION=$(((CURRENT_POSITION + count - 1) % count))
}

page_down() {
    local count=${#VISIBLE_NODES[@]}

    [ "$count" -gt 0 ] || return 0
    CURRENT_POSITION=$((CURRENT_POSITION + TUI_NODE_CAPACITY))
    if [ "$CURRENT_POSITION" -ge "$count" ]; then
        CURRENT_POSITION=$((count - 1))
    fi
}

page_up() {
    [ "${#VISIBLE_NODES[@]}" -gt 0 ] || return 0
    CURRENT_POSITION=$((CURRENT_POSITION - TUI_NODE_CAPACITY))
    [ "$CURRENT_POSITION" -ge 0 ] || CURRENT_POSITION=0
}

set_current_node() {
    local node_index=$1
    local position

    for ((position = 0; position < ${#VISIBLE_NODES[@]}; position++)); do
        if [ "${VISIBLE_NODES[$position]}" -eq "$node_index" ]; then
            CURRENT_POSITION=$position
            return 0
        fi
    done
    return 1
}

expand_current_node() {
    local node_index

    [ "${#VISIBLE_NODES[@]}" -gt 0 ] || return 0
    node_index=${VISIBLE_NODES[$CURRENT_POSITION]}
    [ "${NODE_TOOL_INDEXES[$node_index]}" -lt 0 ] || return 0
    EXPANDED_NODES[$node_index]=1
    rebuild_visible_nodes
    set_current_node "$node_index"
}

collapse_node() {
    local candidate
    local node_index=$1

    for ((candidate = 0; candidate < NODE_COUNT; candidate++)); do
        if [ "${NODE_TOOL_INDEXES[$candidate]}" -lt 0 ] &&
            node_is_descendant "$candidate" "$node_index"; then
            EXPANDED_NODES[$candidate]=0
        fi
    done
}

collapse_current_node() {
    local node_index
    local target

    [ "${#VISIBLE_NODES[@]}" -gt 0 ] || return 0
    node_index=${VISIBLE_NODES[$CURRENT_POSITION]}
    target=$node_index
    if [ "${NODE_TOOL_INDEXES[$node_index]}" -ge 0 ] ||
        [ "${EXPANDED_NODES[$node_index]}" -eq 0 ]; then
        target=${NODE_PARENTS[$node_index]}
    fi
    [ "$target" -ge 0 ] || return 0
    collapse_node "$target"
    rebuild_visible_nodes
    set_current_node "$target"
}

print_confirmation_tree() {
    local indent
    local node_index
    local tool_index

    for ((node_index = 0; node_index < NODE_COUNT; node_index++)); do
        tool_index=${NODE_TOOL_INDEXES[$node_index]}
        if [ "${NODE_SELECTED_TOOLS[$node_index]}" -gt 0 ]; then
            printf -v indent '%*s' "$((${NODE_DEPTHS[$node_index]} * 2))" ''
            if [ "$tool_index" -lt 0 ]; then
                printf '%s%s\n' "$indent" "${NODE_LABELS[$node_index]}"
            else
                printf '%s- %s\n' "$indent" "${NODE_LABELS[$node_index]}"
            fi
        fi
    done
}

confirm_selection() {
    local answer
    local mode_label='Install'

    [ "$MODE" = 'update' ] && mode_label='Update'
    if [ "$SELECTED_TOOL_COUNT" -eq 0 ]; then
        TUI_MESSAGE='Select at least one item'
        return 0
    fi

    TUI_MESSAGE=''
    restore_terminal
    printf '\n%s selected tools:\n\n' "$mode_label"
    print_confirmation_tree
    printf '\n%s %s selected tools? [y/N] ' "$mode_label" "$SELECTED_TOOL_COUNT"
    IFS= read -r answer || answer=''
    case "$answer" in
        y|Y)
            ACTION='execute'
            return 0
            ;;
    esac
    activate_terminal
}

read_tui_key() {
    local remainder=''

    TUI_KEY=''
    IFS= read -r -n 1 TUI_KEY || return $?
    if [ "$TUI_KEY" = $'\033' ]; then
        IFS= read -r -n 2 -t 1 remainder || true
        TUI_KEY="${TUI_KEY}${remainder}"
    fi
}

toggle_mode() {
    if [ "$MODE" = install ]; then
        MODE='update'
    else
        MODE='install'
    fi
    clear_selection
}

handle_tui_key() {
    case "$1" in
        ' ') toggle_current_node ;;
        a) toggle_all_tools ;;
        $'\t') toggle_mode ;;
        h|$'\033[D'|$'\033OD') collapse_current_node ;;
        l|$'\033[C'|$'\033OC') expand_current_node ;;
        j|$'\033[B'|$'\033OB') move_down ;;
        k|$'\033[A'|$'\033OA') move_up ;;
        $'\025') page_up ;;
        $'\004') page_down ;;
        q)
            ACTION='quit'
            restore_terminal
            ;;
        ''|$'\r') confirm_selection ;;
    esac
}

run_tui() {
    if [ ! -t 0 ] || [ ! -t 1 ]; then
        printf 'hostinit requires an interactive terminal\n' >&2
        return 1
    fi
    STTY_STATE=$(stty -g) || return $?
    activate_terminal || return $?
    printf 'hostinit - %s\033[K\n\033[K\nChecking installed tools...\033[K\n\033[J' "$PLATFORM"
    initialize_tui || return $?

    while [ -z "$ACTION" ]; do
        render_tui
        read_tui_key || return $?
        TUI_MESSAGE=''
        handle_tui_key "$TUI_KEY" || return $?
    done
    return 0
}

apt_command() {
    if [ "$EUID" -eq 0 ]; then
        apt-get "$@"
    else
        sudo apt-get "$@"
    fi
}

refresh_apt_metadata() {
    [ "$APT_METADATA_REFRESHED" -eq 0 ] || return 0
    print_step 'refreshing:' 'apt metadata'
    run_checked apt_command update
    APT_METADATA_REFRESHED=1
}

refresh_brew_metadata() {
    [ "$BREW_METADATA_REFRESHED" -eq 0 ] || return 0
    print_step 'refreshing:' 'brew metadata'
    run_checked brew update
    BREW_METADATA_REFRESHED=1
    export HOMEBREW_NO_AUTO_UPDATE=1
}

apt_package_installed() {
    local output
    local status

    if [ "$APT_INSTALLED_CACHE_READY" -eq 0 ]; then
        output=$(dpkg-query -W -f='${binary:Package}\t${Status}\n' 2>&1)
        status=$?
        [ "$status" -eq 0 ] || { printf '%s\n' "$output" >&2; return "$status"; }
        APT_INSTALLED_PACKAGES=$(printf '%s\n' "$output" | awk '
            $2 == "install" && $3 == "ok" && $4 == "installed" {
                print $1
                package = $1
                sub(/:[^:]+$/, "", package)
                if (package != $1) print package
            }
        ')
        status=$?
        [ "$status" -eq 0 ] || return "$status"
        APT_INSTALLED_CACHE_READY=1
    fi

    installed_list_contains "$APT_INSTALLED_PACKAGES" "$1"
}

apt_package_has_update() {
    local candidate
    local installed
    local policy
    local status

    installed=$(dpkg-query -W -f='${Version}' "$1" 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$installed" >&2; exit "$status"; }
    policy=$(LC_ALL=C apt-cache policy "$1" 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$policy" >&2; exit "$status"; }
    candidate=$(printf '%s\n' "$policy" |
        awk '$1 == "Candidate:" {print $2; exit}')
    status=$?
    [ "$status" -eq 0 ] || exit "$status"
    [ -n "$candidate" ] && [ "$candidate" != '(none)' ] || return 1
    dpkg --compare-versions "$candidate" gt "$installed"
    status=$?
    case "$status" in
        0) return 0 ;;
        1) return 1 ;;
        *) exit "$status" ;;
    esac
}

installed_list_contains() {
    local installed=$1
    local package=$2

    case $'\n'"$installed"$'\n' in
        *$'\n'"$package"$'\n'*) return 0 ;;
        *) return 1 ;;
    esac
}

package_manager_label() {
    case "$1" in
        apt) printf 'apt' ;;
        brew:formula) printf 'brew' ;;
        brew:cask) printf 'brew cask' ;;
        *) return 1 ;;
    esac
}

package_is_installed() {
    local kind=$1
    local package=$2

    case "$kind" in
        apt) apt_package_installed "$package" ;;
        brew:formula) brew_formula_installed "$package" ;;
        brew:cask) brew_cask_installed "$package" ;;
        *) return 2 ;;
    esac
}

tool_package_kind() {
    local source=${TOOL_SOURCES[$1]}

    if [ "$source" = brew ]; then
        printf 'brew:%s' "${TOOL_BREW_TYPES[$1]}"
    else
        printf '%s' "$source"
    fi
}

load_brew_installed_cache() {
    local brew_bin
    local output
    local status

    [ "$BREW_INSTALLED_CACHE_READY" -eq 0 ] || return 0
    if command -v _brew_find >/dev/null 2>&1; then
        if ! brew_bin=$(_brew_find); then
            BREW_INSTALLED_CACHE_READY=1
            return 0
        fi
    else
        if ! brew_bin=$(command -v brew); then
            BREW_INSTALLED_CACHE_READY=1
            return 0
        fi
    fi

    output=$("$brew_bin" list --formula 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$output" >&2; return "$status"; }
    BREW_INSTALLED_FORMULAE=$output

    output=$("$brew_bin" list --cask 2>&1)
    status=$?
    [ "$status" -eq 0 ] || { printf '%s\n' "$output" >&2; return "$status"; }
    BREW_INSTALLED_CASKS=$output
    BREW_INSTALLED_CACHE_READY=1
}

brew_formula_installed() {
    load_brew_installed_cache || return $?
    installed_list_contains "$BREW_INSTALLED_FORMULAE" "$1"
}

brew_cask_installed() {
    load_brew_installed_cache || return $?
    installed_list_contains "$BREW_INSTALLED_CASKS" "$1"
}

# Custom modules expose only supported actions. Updates also require an
# installation check; actions without one remain available in install mode.
tool_supports_action() {
    local tool_index=$1
    local action=$2

    [ "${TOOL_SOURCES[$tool_index]}" = custom ] || return 0
    declare -F "${TOOL_NAMES[$tool_index]}_${action}" >/dev/null || return 1
    if [ "$action" = update ]; then
        declare -F "${TOOL_NAMES[$tool_index]}_is_installed" >/dev/null || return 1
    fi
    return 0
}

tool_is_installed() {
    local kind
    local package
    local tool_index=$1

    if [ "${TOOL_SOURCES[$tool_index]}" = custom ]; then
        declare -F "${TOOL_NAMES[$tool_index]}_is_installed" >/dev/null || return 1
        "${TOOL_NAMES[$tool_index]}_is_installed"
        return $?
    fi

    BATCH_PACKAGES=()
    append_tool_packages "$tool_index"
    kind=$(tool_package_kind "$tool_index") || return $?
    for package in "${BATCH_PACKAGES[@]}"; do
        package_is_installed "$kind" "$package" || return $?
    done
    return 0
}

update_packages() {
    local kind=$1
    local manager
    local outdated
    local package
    local status
    local -a current_packages
    local -a update_packages

    shift
    manager=$(package_manager_label "$kind") || exit $?
    current_packages=()
    update_packages=()
    case "$kind" in
        brew:*)
            outdated=$(brew outdated "--${kind#brew:}" --quiet 2>&1)
            status=$?
            [ "$status" -eq 0 ] || { printf '%s\n' "$outdated" >&2; exit "$status"; }
            ;;
    esac

    for package in "$@"; do
        if { [ "$kind" = apt ] && apt_package_has_update "$package"; } ||
            { [ "$kind" != apt ] && installed_list_contains "$outdated" "$package"; }; then
            update_packages[${#update_packages[@]}]=$package
        else
            current_packages[${#current_packages[@]}]=$package
        fi
    done
    if [ "${#update_packages[@]}" -eq 0 ]; then
        print_skip "not updated (${manager}):" "${current_packages[@]}"
        return 1
    fi

    print_step "updating (${manager}):" "${update_packages[@]}"
    case "$kind" in
        apt)
            run_checked apt_command install --only-upgrade -y "${update_packages[@]}"
            ;;
        brew:formula)
            run_checked brew upgrade "${update_packages[@]}"
            ;;
        brew:cask)
            run_checked brew upgrade --cask "${update_packages[@]}"
            ;;
    esac
    print_success "updated (${manager}):" "${update_packages[@]}"
    if [ "${#current_packages[@]}" -gt 0 ]; then
        print_skip "not updated (${manager}):" "${current_packages[@]}"
    fi
    return 0
}

filter_batch_packages() {
    local kind=$1
    local manager
    local mode=$2
    local package
    local installed
    local -a skipped_packages

    FILTERED_PACKAGES=()
    skipped_packages=()
    manager=$(package_manager_label "$kind") || return $?
    for package in "${BATCH_PACKAGES[@]}"; do
        installed=1
        package_is_installed "$kind" "$package" && installed=0

        if { [ "$mode" = 'install' ] && [ "$installed" -ne 0 ]; } ||
            { [ "$mode" = 'update' ] && [ "$installed" -eq 0 ]; }; then
            FILTERED_PACKAGES[${#FILTERED_PACKAGES[@]}]=$package
        else
            skipped_packages[${#skipped_packages[@]}]=$package
        fi
    done

    if [ "${#skipped_packages[@]}" -gt 0 ]; then
        if [ "$mode" = install ]; then
            print_skip 'skipped:' "${skipped_packages[@]}"
        else
            print_skip "not updated (${manager}, not installed):" "${skipped_packages[@]}"
        fi
    fi
}

run_package_batch() {
    local kind=$1
    local manager
    local mode=$2
    local tool_index

    shift 2
    manager=$(package_manager_label "$kind") || exit $?
    BATCH_PACKAGES=()
    for tool_index in "$@"; do
        append_tool_packages "$tool_index"
    done
    filter_batch_packages "$kind" "$mode"
    if [ "${#FILTERED_PACKAGES[@]}" -eq 0 ]; then
        [ "$mode" = update ] && return 1
        return 0
    fi

    case "$kind" in
        apt) refresh_apt_metadata ;;
        brew:*) refresh_brew_metadata ;;
    esac
    if [ "$mode" = update ]; then
        update_packages "$kind" "${FILTERED_PACKAGES[@]}"
        return $?
    fi

    print_step "installing (${manager}):" "${FILTERED_PACKAGES[@]}"
    case "$kind" in
        apt)
            run_checked apt_command install -y "${FILTERED_PACKAGES[@]}"
            APT_INSTALLED_CACHE_READY=0
            ;;
        brew:formula)
            run_checked brew install --no-ask "${FILTERED_PACKAGES[@]}"
            BREW_INSTALLED_CACHE_READY=0
            ;;
        brew:cask)
            run_checked brew install --cask --no-ask "${FILTERED_PACKAGES[@]}"
            BREW_INSTALLED_CACHE_READY=0
            ;;
    esac
    print_success "installed (${manager}):" "${FILTERED_PACKAGES[@]}"
}

run_custom_tool() {
    local tool_index=$1
    local tool_label=${TOOL_LABELS[$tool_index]}
    local function_prefix=${TOOL_NAMES[$tool_index]}
    local status

    if ! tool_supports_action "$tool_index" "$MODE"; then
        print_skip "skipped (${MODE} not supported): ${tool_label}"
        return 0
    fi

    tool_is_installed "$tool_index"
    status=$?
    case "$MODE:$status" in
        install:0)
            print_skip "skipped: ${tool_label}"
            return 0
            ;;
        install:1)
            print_step "installing: ${tool_label}"
            run_checked "${function_prefix}_install"
            print_success "installed: ${tool_label}"
            return 0
            ;;
        update:0) ;;
        update:1)
            print_skip "not updated (not installed): ${tool_label}"
            return 0
            ;;
        *)
            exit "$status"
            ;;
    esac

    print_step "updating: ${tool_label}"
    "${function_prefix}_update"
    status=$?
    case "$status" in
        0) print_success "updated: ${tool_label}" ;;
        1) print_skip "not updated: ${tool_label}" ;;
        *) exit "$status" ;;
    esac
}

flush_package_batch() {
    local status

    [ "${#BATCH_TOOL_INDEXES[@]}" -gt 0 ] || return 0
    run_package_batch "$BATCH_KIND" "$MODE" "${BATCH_TOOL_INDEXES[@]}"
    status=$?
    if [ "$MODE" != update ] || [ "$status" -ne 1 ]; then
        [ "$status" -eq 0 ] || exit "$status"
    fi
    BATCH_KIND=''
    BATCH_TOOL_INDEXES=()
}

execute_selected() {
    local index
    local kind

    BATCH_KIND=''
    BATCH_TOOL_INDEXES=()
    for ((index = 0; index < TOOL_COUNT; index++)); do
        if [ "${TOOL_ENABLED[$index]}" -ne 1 ] || [ "${SELECTED_TOOLS[$index]}" -ne 1 ]; then
            continue
        fi

        if [ "${TOOL_SOURCES[$index]}" = 'custom' ]; then
            flush_package_batch
            run_custom_tool "$index"
        else
            kind=$(tool_package_kind "$index") || exit $?
            if [ -n "$BATCH_KIND" ] && [ "$BATCH_KIND" != "$kind" ]; then
                flush_package_batch
            fi
            BATCH_KIND=$kind
            BATCH_TOOL_INDEXES[${#BATCH_TOOL_INDEXES[@]}]=$index
        fi
    done
    flush_package_batch
}

main() {
    local status

    if [ "$#" -ne 0 ]; then
        printf 'hostinit.sh does not accept arguments\n' >&2
        return 2
    fi
    if ! detect_platform; then
        printf 'unsupported platform\n' >&2
        return 1
    fi

    configure_tools
    load_custom_modules
    run_tui
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    [ "$ACTION" = 'execute' ] || return 0
    restore_terminal
    execute_selected
}

main "$@"
exit $?
